xpath.script:
{
    const info = odoo.__session_info__ || {};
    const pref = info.xet_theme;
    if (pref) {
        let theme = pref;
        if (pref === "system") {
            theme = window.matchMedia("(prefers-color-scheme: dark)").matches
                ? "dark_blue"
                : "light";
        }
        if (["dark_blue", "light", "graphite"].indexOf(theme) === -1) {
            theme = "dark_blue";
        }
        document.documentElement.dataset.xetThemePref = pref;
        document.documentElement.dataset.xetTheme = theme;
    }
}
